use std::fs;
fn main(){let old="/tmp/zopro-arithmetic-leaves";let r="/tmp/zopro-arithmetic-leaves-corrected";for name in ["patch.rs","setup.rs","prepare.rs","analyze.rs","close.rs","driver.rs","design.md","serial-scopes.md","pre-capture-correction.md"]{let mut text=fs::read_to_string(format!("{old}/{name}")).unwrap().replace(old,r);if name=="patch.rs"{text=text.replace("pub(super) fn msm<C:","pub(super) fn msm_canonical<C:");}if ["prepare.rs","analyze.rs","close.rs","design.md"].contains(&name){text=text.replace("7205","7233").replace("7187","7215").replace("7177","7205");}if name=="prepare.rs"{text=text.replace("\"/tmp/zopro-sdk-paired-control/proof-inventory.json\"]","\"/tmp/zopro-sdk-paired-control/proof-inventory.json\",\"/tmp/zopro-arithmetic-leaves/proof-inventory.json\"]");let needle="let a=read(r.join(\"native/trace/artifacts.json\"));let mut jobs=Vec::new();";let replacement=r#"let a=read(r.join("native/trace/artifacts.json"));let checklog=fs::read_to_string(r.join("preflight/1x2-on/stdout.log")).unwrap();let g:Value=serde_json::from_str(checklog.lines().find_map(|l|l.strip_prefix("GRAPH ")).unwrap()).unwrap();let raw=fs::read(g["file"].as_str().unwrap()).unwrap();let records:Vec<[u64;10]>=raw.chunks_exact(80).map(|e|core::array::from_fn(|i|u64::from_le_bytes(e[i*8..i*8+8].try_into().unwrap()))).collect();for kind in 0..=6{assert_eq!(records.iter().filter(|e|e[2]==kind).count(),1,"semantic preflight kind{kind}");}let event=|kind|records.iter().find(|e|e[2]==kind).unwrap();assert_eq!(event(1)[1],event(6)[0]);assert_eq!(event(3)[1],event(5)[0]);save(r.join("semantic-preflight.json"),&json!({"canonical_A_query_hook_present":true,"A_kernel_parent_is_A_query":true,"G2_kernel_parent_is_G2_query":true,"all7boundary_kinds_once":true,"dropped":g["thread_dropped"]}));add(r.join("semantic-preflight.json"),&mut pins);let mut jobs=Vec::new();"#;assert!(text.contains(needle));text=text.replacen(needle,replacement,1);}if name=="close.rs"{let needle="save(d.join(\"artifact-index.json\"),&json!(index));";let replacement=r#"let first=Path::new("/tmp/zopro-arithmetic-leaves");let mut first_index=BTreeMap::new();archive(first,first,&d.join("artifacts/initial-capture"),&mut first_index);for(rel,h)in first_index{assert!(index.insert(format!("initial-capture/{rel}"),h).is_none());}for(rel,h)in &index{assert_eq!(&hash(d.join("artifacts").join(rel)),h);}save(d.join("artifact-index.json"),&json!(index));"#;assert!(text.contains(needle));text=text.replacen(needle,replacement,1);let needle="let audit=json!";let at=text.find(needle).unwrap();text.insert_str(at,"let initial=read(\"/tmp/zopro-arithmetic-leaves/initial-analysis.json\");assert_eq!(initial[\"SDK_requests\"],652);assert_eq!(initial[\"next_prior_count\"],7205);\n");let needle="let mut md=format!";let at=text.find(needle).unwrap();text.insert_str(at,"let combined=json!({\"initial\":initial,\"corrected_SDK_requests\":652,\"corrected_exports\":28,\"combined_SDK_requests\":1304,\"combined_distinct_exports\":56,\"combined_proof_public_members\":112,\"next_prior_count\":7233,\"initial_attribution_failure_retained\":true,\"adopted\":false,\"goal_achieved\":false});save(r.join(\"combined-series.json\"),&combined);\n");}
 fs::write(format!("{r}/{name}"),text).unwrap();}
 let notes="\nThe first measured series completed all652 SDK calls and28 independent Gnark exports. Its strict decoder rejected missing whole-A-query metadata: the hook was on msm_affine::msm but the canonical-wire path calls msm_canonical (aliased as msm in lib.rs). All first-series sources, timings, graphs and proof members remain under /tmp/zopro-arithmetic-leaves. A separate corrected source/build/output directory moves ONLY that hook to msm_canonical. Corrected preflight now explicitly checks all7 boundary kinds and kernel/query parent IDs before matrix capture. The first series remains invalid for query attribution and is not discarded or averaged away. Its28exports extend7177to7205; corrected exports extendto7233. This is a source instrumentation repair, not an unchanged timing rerun or gate relaxation.\n";for name in ["pre-capture-correction.md","design.md"]{let p=format!("{r}/{name}");let mut s=fs::read_to_string(&p).unwrap();s.push_str(notes);fs::write(p,s).unwrap();}println!("Created distinct corrected source; exactcanonical_A entry; allfirst-seriesresultsretained");}
